/**
 * MicroPython's API, as the official stubs describe it.
 *
 * `micropython-stubs.json` is GENERATED by `scripts/gen-micropython-stubs.py`
 * from the `micropython-*-stubs` packages on PyPI (the MicroPython stubs
 * project, MIT licence — the same `.pyi` files Pylance and Pyright read). It
 * holds every public module, class, method, function and constant for the
 * rp2 and esp32 ports plus MicroPython's slice of the standard library, each
 * with its signatures and the docstring from the MicroPython docs.
 *
 * It complements, rather than replaces, the hand-written catalogue in
 * `micropython-symbols.ts`: that one is small, dialect-scoped and also feeds the
 * blocks editor; this one is broad and only ever offered to a MicroPython (or
 * not-yet-known) session.
 *
 * The data is ~370 KiB, so it is loaded lazily with a dynamic import (its own
 * chunk) the first time the editor asks for it. Until it arrives, completions
 * fall back to the curated catalogue alone.
 */

/** One way to call a function, method or constructor. */
export interface StubSignature {
  /** `Pin(id, mode: int = -1, pull: int = -1, *, value=None, …)` */
  label: string
  /** Each parameter exactly as it appears inside `label` (no bare `*`). */
  params: string[]
  /** A docstring specific to this overload, when it differs from the member's. */
  doc?: string
  /** The annotated return type, e.g. `int` or `StateMachine`. */
  returns?: string
}

/** A module member, or a member of a class. */
export interface StubMember {
  kind: 'function' | 'method' | 'class' | 'constant' | 'variable'
  /** Markdown, converted from the stub's reStructuredText docstring. */
  doc?: string
  signatures?: StubSignature[]
  /** A class's own members (methods, constants, nested classes). */
  members?: Record<string, StubMember>
  /** Base classes, by name — looked up in the same module. */
  bases?: string[]
  /** Only some ports have this (e.g. `['rp2']`). Absent means every port. */
  ports?: string[]
  /** Annotated type of a constant/variable. */
  type?: string
  /** `async def` — awaitable. */
  async?: boolean
}

export interface StubModule {
  doc?: string
  /** The module's page in the official MicroPython docs. */
  url?: string
  ports?: string[]
  members: Record<string, StubMember>
}

export interface StubCatalogue {
  source: { project: string; license: string; packages: Record<string, string>; ports: string[] }
  /** `utime` → `time`: the u-prefixed names MicroPython still accepts. */
  aliases: Record<string, string>
  modules: Record<string, StubModule>
}

let loaded: StubCatalogue | null = null
let loading: Promise<StubCatalogue | null> | null = null

/**
 * Start (or join) loading the catalogue. Never rejects: a failed load leaves
 * completions on the curated catalogue, which is what they did before.
 */
export function loadMicropythonStubs(): Promise<StubCatalogue | null> {
  if (!loading) {
    loading = import('./micropython-stubs.json')
      .then((m) => {
        loaded = ((m as { default?: unknown }).default ?? m) as unknown as StubCatalogue
        return loaded
      })
      .catch(() => null)
  }
  return loading
}

/** The catalogue if it has arrived, else null. Synchronous: for completion requests. */
export function micropythonStubs(): StubCatalogue | null {
  return loaded
}

/** Install a catalogue directly (tests), or clear it with null. */
export function setMicropythonStubs(catalogue: StubCatalogue | null): void {
  loaded = catalogue
  loading = catalogue ? Promise.resolve(catalogue) : null
}

/** The canonical module name: `utime` → `time`, `machine` → `machine`. */
export function canonicalModule(catalogue: StubCatalogue, name: string): string {
  return catalogue.aliases[name] ?? name
}

/** A module by name or u-alias. */
export function stubModule(catalogue: StubCatalogue, name: string): StubModule | undefined {
  return catalogue.modules[canonicalModule(catalogue, name)]
}
